!function(){
  const C=window.WOONGBI_ANALYTICS||{},E=C.siteAnalyticsEndpoint;
  let sessionId="";
  try{
    sessionId=sessionStorage.getItem("wb_site_session_v1")||"";
    if(!sessionId){
      sessionId=crypto.randomUUID?crypto.randomUUID():[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,"0")).join("");
      sessionStorage.setItem("wb_site_session_v1",sessionId);
    }
  }catch(e){
    sessionId=crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2)+Date.now().toString(36);
  }

  function device(){
    const w=Math.max(document.documentElement.clientWidth||0,innerWidth||0);
    return w<=767?"mobile":w<=1100?"tablet":"desktop";
  }
  function safeGet(storage,key){
    try{return storage&&storage.getItem?storage.getItem(key)||"":""}catch(e){return""}
  }
  function safeSet(storage,key,value){
    try{if(storage&&storage.setItem)storage.setItem(key,String(value||""))}catch(e){}
  }
  const persistentStorage=typeof localStorage!=="undefined"?localStorage:sessionStorage;
  function classifyHost(host){
    const h=String(host||"").toLowerCase().replace(/^www\./,"");
    if(!h)return"direct";
    if(h===location.hostname)return"internal";
    if(/(^|\.)search\.naver\.com$/.test(h))return h;
    if(/(^|\.)blog\.naver\.com$/.test(h))return"naver-blog";
    if(/(^|\.)(map|m\.place)\.naver\.com$/.test(h))return"naver-place";
    if(/(^|\.)google\./.test(h))return"google-search";
    if(/(^|\.)search\.daum\.net$/.test(h)||h==="daum.net")return"daum-search";
    if(/(^|\.)bing\.com$/.test(h))return"bing-search";
    if(/(^|\.)instagram\.com$/.test(h))return"instagram";
    if(/(^|\.)threads\.(net|com)$/.test(h))return"threads";
    if(/(^|\.)(youtube\.com|youtu\.be)$/.test(h))return"youtube";
    if(/(^|\.)kakao\.com$/.test(h)||h==="pf.kakao.com")return"kakao";
    if(/(^|\.)daangn\.com$/.test(h))return"daangn";
    return h.slice(0,80)||"other";
  }
  function taggedSource(params){
    const raw=(params.get("utm_source")||params.get("src")||"").trim().toLowerCase();
    const aliases={
      "naver":"naver-search","naver-search":"naver-search","naver-place":"naver-place","naver-blog":"naver-blog",
      "google":"google-search","google-business":"google-business","daum":"daum-search","bing":"bing-search",
      "instagram":"instagram","threads":"threads","youtube":"youtube","kakao":"kakao","kakao-channel":"kakao-channel",
      "kakao-map":"kakao-map","daangn":"daangn"
    };
    return aliases[raw]||(raw.startsWith("seo-")?raw:"");
  }
  const params=new URLSearchParams(location.search);
  let source=taggedSource(params);
  if(source){
    safeSet(sessionStorage,"wb_site_source_v1",source);
  }else{
    source=safeGet(sessionStorage,"wb_site_source_v1");
    if(!source){
      try{source=document.referrer?classifyHost(new URL(document.referrer).hostname):"direct"}catch(e){source="other"}
      safeSet(sessionStorage,"wb_site_source_v1",source);
    }
  }

  let firstSource=safeGet(persistentStorage,"wb_site_first_source_v1");
  if(!firstSource){
    firstSource=source==="internal"?"direct":source;
    safeSet(persistentStorage,"wb_site_first_source_v1",firstSource);
  }
  let landing=safeGet(sessionStorage,"wb_site_landing_v1");
  if(!landing){
    landing=(location.pathname+location.search).slice(0,220);
    safeSet(sessionStorage,"wb_site_landing_v1",landing);
  }
  const campaign=(params.get("utm_campaign")||safeGet(sessionStorage,"wb_site_campaign_v1")).slice(0,100);
  const medium=(params.get("utm_medium")||safeGet(sessionStorage,"wb_site_medium_v1")).slice(0,80);
  const term=(params.get("utm_term")||params.get("n_keyword")||safeGet(sessionStorage,"wb_site_term_v1")).slice(0,100);
  if(campaign)safeSet(sessionStorage,"wb_site_campaign_v1",campaign);
  if(medium)safeSet(sessionStorage,"wb_site_medium_v1",medium);
  if(term)safeSet(sessionStorage,"wb_site_term_v1",term);
  let referrerHost="";
  try{referrerHost=document.referrer?new URL(document.referrer).hostname.replace(/^www\./,"").slice(0,80):""}catch(e){}

  window.woongbiSiteAnalyticsContext=()=>({
    session_id:sessionId,
    path:location.pathname,
    source:source||"direct",
    first_source:firstSource||"direct",
    landing_path:landing||location.pathname,
    campaign,medium,term,
    referrer_host:referrerHost,
    device:device()
  });

  if(!E||location.hostname!=="woongbts.github.io"||navigator.webdriver||navigator.doNotTrack==="1"||window.woongbiAnalyticsOwnerExcluded?.())return;
  function send(){
    const c=window.woongbiSiteAnalyticsContext();
    fetch(E,{method:"POST",mode:"cors",credentials:"omit",keepalive:!0,headers:{"Content-Type":"text/plain;charset=UTF-8"},body:JSON.stringify(c)}).catch(()=>{});
  }
  if(document.visibilityState==="prerender"){
    document.addEventListener("visibilitychange",function onVisible(){
      if(document.visibilityState!=="prerender"){document.removeEventListener("visibilitychange",onVisible);send()}
    });
  }else send();
}();